package cn.gmiya.malodylink;

import android.app.*;
import android.content.Context;
import android.os.*;
import android.text.*;
import android.view.*;
import android.view.inputmethod.InputMethodManager;
import android.widget.*;
import org.json.JSONObject;
import java.util.*;
import java.util.function.*;

public final class SongPanel extends LinearLayout {
    private final SongCatalogue catalogue;private List<SongCatalogue.Song> results;private final Handler handler=new Handler(Looper.getMainLooper());private final EditText search;private final TextView count;private final BaseAdapter adapter;private final Consumer<SongCatalogue.Song> open;private int mode,columns;private boolean hideUngraded;
    public SongPanel(Activity host,Engine engine,String query,Consumer<String> remember,BiConsumer<SongCatalogue.Song,Integer> rank,boolean chooser){this(host,engine,query,0,(m,q)->remember.accept(q),rank,chooser);}
    public SongPanel(Activity host,Engine engine,String query,int selectedMode,BiConsumer<Integer,String> remember,BiConsumer<SongCatalogue.Song,Integer> rank,boolean chooser){super(host);mode=Math.max(0,Math.min(SongCatalogue.KEYS,selectedMode));setOrientation(1);setBackground(chooser?null:new CharacterBackdrop(host,3));setPadding(AppUi.dp(host,chooser?0:16),AppUi.dp(host,chooser?8:16),AppUi.dp(host,chooser?0:16),0);catalogue=new SongCatalogue(engine.charts());hideUngraded=host.getSharedPreferences("song-search",0).getBoolean("hide_ungraded",false);columns=Math.max(1,Math.min(5,host.getSharedPreferences("song-search",0).getInt("columns",3)));
        addView(AppUi.text(host,chooser?"选择歌曲":"歌曲信息",chooser?18:26,AppUi.INK,true));AppUi.space(this,12);addView(AppUi.text(host,"先选择搜索类型，再输入关键词、等级或键数",13,AppUi.MUTED,false));LinearLayout filterRow=new LinearLayout(host);Spinner selector=new Spinner(host);ArrayAdapter<String> choices=new ArrayAdapter<>(host,android.R.layout.simple_spinner_item,new String[]{"综合","曲名","歌手","谱师","等级","键数"});choices.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);selector.setAdapter(choices);selector.setSelection(mode);filterRow.addView(selector,new LayoutParams(AppUi.dp(host,110),AppUi.dp(host,52)));addView(filterRow);search=new EditText(host);search.setTextSize(16);search.setTextColor(AppUi.INK);search.setHintTextColor(AppUi.MUTED);search.setSingleLine(true);search.setHint("输入关键词");search.setFilters(new InputFilter[]{new InputFilter.LengthFilter(100)});search.setImeOptions(android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH);filterRow.addView(search,new LayoutParams(0,AppUi.dp(host,52),1));CheckBox hideUnknown=new CheckBox(host);hideUnknown.setText("隐藏未提供等级的歌曲");hideUnknown.setTextColor(AppUi.INK);hideUnknown.setTextSize(14);hideUnknown.setMinHeight(AppUi.dp(host,48));hideUnknown.setChecked(hideUngraded);addView(hideUnknown);LinearLayout displayRow=new LinearLayout(host);displayRow.setGravity(Gravity.CENTER_VERTICAL);displayRow.addView(AppUi.text(host,"每行",13,AppUi.MUTED,false));Spinner columnPicker=new Spinner(host);ArrayAdapter<String> columnChoices=new ArrayAdapter<>(host,android.R.layout.simple_spinner_item,new String[]{"1列","2列","3列","4列","5列"});columnChoices.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);columnPicker.setAdapter(columnChoices);columnPicker.setSelection(columns-1);columnPicker.setContentDescription("歌曲卡片每行列数");displayRow.addView(columnPicker,new LayoutParams(AppUi.dp(host,96),AppUi.dp(host,48)));count=AppUi.text(host,"",12,AppUi.MUTED,false);count.setGravity(Gravity.END|Gravity.CENTER_VERTICAL);count.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);displayRow.addView(count,new LayoutParams(0,AppUi.dp(host,48),1));addView(displayRow);
        results=catalogue.search(query,mode,hideUngraded);open=song->{((InputMethodManager)host.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);if(chooser){List<JSONObject> visible=visibleCharts(song);if(!visible.isEmpty())rank.accept(song,visible.get(0).optInt("cid"));}else details(host,song,rank);};
        adapter=new BaseAdapter(){
            public int getCount(){return results.size();}
            public Object getItem(int position){return results.get(position);}
            public long getItemId(int position){return results.get(position).sid;}
            public View getView(int position,View convert,ViewGroup parent){
                Holder h;
                if(convert==null){
                    h=new Holder();LinearLayout card=AppUi.column(host,8);card.setGravity(Gravity.CENTER_HORIZONTAL);
                    android.graphics.drawable.GradientDrawable surface=AppUi.background(host,AppUi.CARD);surface.setStroke(AppUi.dp(host,1),AppUi.BORDER);
                    card.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x24076d78),surface,null));card.setClipToOutline(true);
                    h.art=new ImageView(host);h.art.setScaleType(ImageView.ScaleType.FIT_CENTER);card.addView(h.art,new LayoutParams(-1,AppUi.dp(host,56)));AppUi.space(card,6);
                    h.title=AppUi.text(host,"",14,AppUi.INK,true);h.title.setMinLines(2);h.title.setMaxLines(2);h.title.setGravity(Gravity.CENTER);h.title.setEllipsize(TextUtils.TruncateAt.END);card.addView(h.title,new LayoutParams(-1,-2));
                    h.artist=AppUi.text(host,"",12,AppUi.MUTED,false);h.artist.setSingleLine(true);h.artist.setGravity(Gravity.CENTER);h.artist.setEllipsize(TextUtils.TruncateAt.END);card.addView(h.artist,new LayoutParams(-1,-2));AppUi.space(card,4);
                    h.level=AppUi.text(host,"",13,AppUi.ACCENT,true);h.level.setSingleLine(true);h.level.setGravity(Gravity.CENTER);h.level.setEllipsize(TextUtils.TruncateAt.END);card.addView(h.level,new LayoutParams(-1,-2));
                    convert=card;convert.setTag(h);
                }else h=(Holder)convert.getTag();
                SongCatalogue.Song song=results.get(position);h.title.setText(song.title);h.artist.setText(song.artist.isEmpty()?"歌手未提供":song.artist);
                h.level.setText(SongCatalogue.highestLevelLabel(visibleCharts(song)));h.level.setContentDescription("最高难度等级 "+h.level.getText());
                h.art.setContentDescription(song.title+"曲绘");SongArtwork.load(host,h.art,song);return convert;
            }
        };
        GridView list=new GridView(host);list.setNumColumns(columns);list.setStretchMode(GridView.STRETCH_COLUMN_WIDTH);list.setHorizontalSpacing(AppUi.dp(host,8));list.setVerticalSpacing(AppUi.dp(host,8));list.setSelector(new android.graphics.drawable.ColorDrawable(android.graphics.Color.TRANSPARENT));list.setPadding(0,0,0,AppUi.dp(host,12));list.setClipToPadding(false);list.setAdapter(adapter);list.setOnItemClickListener((p,v,index,id)->open.accept(results.get(index)));addView(list,new LayoutParams(-1,0,1));
        columnPicker.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){columns=position+1;list.setNumColumns(columns);host.getSharedPreferences("song-search",0).edit().putInt("columns",columns).apply();}});
        search.setText(query);count.setText(results.size()+" 首歌曲");Runnable filter=()->{results=catalogue.search(search.getText().toString(),mode,hideUngraded);adapter.notifyDataSetChanged();count.setText(results.isEmpty()?"没有找到匹配歌曲":results.size()+" 首歌曲");};hideUnknown.setOnCheckedChangeListener((v,checked)->{hideUngraded=checked;host.getSharedPreferences("song-search",0).edit().putBoolean("hide_ungraded",checked).apply();handler.removeCallbacks(filter);filter.run();});search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int n){remember.accept(mode,s.toString());handler.removeCallbacks(filter);handler.postDelayed(filter,160);}public void afterTextChanged(Editable e){}});selector.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int position,long id){
            mode=position;String value=search.getText().toString();search.setInputType(mode==SongCatalogue.LEVEL?android.text.InputType.TYPE_CLASS_NUMBER|android.text.InputType.TYPE_NUMBER_FLAG_DECIMAL:android.text.InputType.TYPE_CLASS_TEXT);search.setSingleLine(true);search.setHint(mode==SongCatalogue.LEVEL?"输入显示等级，如 12":mode==SongCatalogue.KEYS?"如 4、4K 或 4键":"输入关键词");remember.accept(mode,value);handler.removeCallbacks(filter);filter.run();
        }});search.setOnEditorActionListener((v,a,event)->{handler.removeCallbacks(filter);filter.run();((InputMethodManager)host.getSystemService(Context.INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(search.getWindowToken(),0);return true;});
    }
    private List<JSONObject> visibleCharts(SongCatalogue.Song song){
        return SongCatalogue.matchingCharts(song,search.getText().toString(),mode,hideUngraded);
    }
    private static final class Holder {ImageView art;TextView title,artist,level;}
    public static void details(Activity host,SongCatalogue.Song song,BiConsumer<SongCatalogue.Song,Integer> rank){ScrollView scroll=new ScrollView(host);LinearLayout body=AppUi.column(host,20);scroll.addView(body);ImageView art=new ImageView(host);art.setScaleType(ImageView.ScaleType.FIT_CENTER);art.setContentDescription(song.title+"曲绘");body.addView(art,new LayoutParams(-1,AppUi.dp(host,200)));SongArtwork.load(host,art,song);AppUi.space(body,12);LinearLayout titleRow=new LinearLayout(host);titleRow.setGravity(Gravity.CENTER_VERTICAL);titleRow.addView(AppUi.text(host,song.title,22,AppUi.INK,true),new LayoutParams(0,-2,1));ImageButton copy=new ImageButton(host);copy.setImageDrawable(new NavIcon(11,AppUi.ACCENT));copy.setScaleType(ImageView.ScaleType.FIT_CENTER);int padding=AppUi.dp(host,13);copy.setPadding(padding,padding,padding,padding);copy.setContentDescription("复制歌曲名称");copy.setTooltipText("复制歌曲名称");copy.setBackground(new android.graphics.drawable.RippleDrawable(android.content.res.ColorStateList.valueOf(0x24076d78),AppUi.background(host,AppUi.SOFT),null));LayoutParams copySize=new LayoutParams(AppUi.dp(host,48),AppUi.dp(host,48));copySize.leftMargin=AppUi.dp(host,8);titleRow.addView(copy,copySize);copy.setOnClickListener(v->{android.content.ClipboardManager clipboard=(android.content.ClipboardManager)host.getSystemService(Context.CLIPBOARD_SERVICE);if(clipboard!=null){clipboard.setPrimaryClip(android.content.ClipData.newPlainText("歌曲名称",song.title));Toast.makeText(host,"已复制歌曲名称",Toast.LENGTH_SHORT).show();}});body.addView(titleRow);body.addView(AppUi.text(host,"歌手 · "+(song.artist.isEmpty()?"未提供":song.artist),16,AppUi.MUTED,false));body.addView(AppUi.text(host,"BPM · "+(song.bpm.isEmpty()?"未提供":song.bpm),16,AppUi.MUTED,false));
        AlertDialog dialog=new AlertDialog.Builder(host).setView(scroll).setNegativeButton("关闭",null).create();body.addView(AppUi.button(host,"评论与评分",()->SongCommunityActivity.open(host,song.charts.get(0).optInt("cid"))));body.addView(AppUi.button(host,"单曲排行榜",()->{dialog.dismiss();rank.accept(song,song.charts.get(0).optInt("cid"));}));
        Map<Integer,TextView> downloads=new HashMap<>();for(JSONObject chart:song.charts){AppUi.space(body,16);LinearLayout card=AppUi.column(host,14);card.setBackground(AppUi.background(host,AppUi.CARD));LinearLayout metadata=new LinearLayout(host);metadata.setGravity(Gravity.CENTER_VERTICAL);metadata.addView(ChartKeyBadge.view(host,chart,28));Space gap=new Space(host);metadata.addView(gap,new LayoutParams(0,1,1));ImageView icon=new ImageView(host);icon.setImageResource(android.R.drawable.stat_sys_download_done);icon.setImageTintList(android.content.res.ColorStateList.valueOf(AppUi.MUTED));icon.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);metadata.addView(icon,new LayoutParams(AppUi.dp(host,18),AppUi.dp(host,18)));TextView value=AppUi.text(host,"—",13,AppUi.MUTED,false);value.setPadding(AppUi.dp(host,4),0,0,0);value.setContentDescription("谱面下载量读取中");metadata.addView(value);downloads.put(chart.optInt("cid"),value);card.addView(metadata);AppUi.space(card,6);card.addView(AppUi.text(host,SongCatalogue.levelLabel(chart)+" · "+chart.optString("version"),16,AppUi.ACCENT,true));String creator=chart.optString("creator");card.addView(AppUi.text(host,"谱师 · "+(creator.isEmpty()?"未提供":creator),14,AppUi.MUTED,false));card.addView(AppUi.button(host,"该谱面排行榜",()->{dialog.dismiss();rank.accept(song,chart.optInt("cid"));}));body.addView(card);}body.setBackgroundColor(AppUi.BG);dialog.show();loadDownloads(host,song,dialog,downloads);}
    private static void showDownloads(Activity host,AlertDialog dialog,Map<Integer,TextView> views,JSONObject doc){host.runOnUiThread(()->{if(host.isDestroyed()||!dialog.isShowing())return;for(Map.Entry<Integer,TextView> entry:views.entrySet()){long count=CommunityData.chartDownloads(doc,entry.getKey());if(count>=0){entry.getValue().setText(String.format(Locale.CHINA,"%,d",count));entry.getValue().setContentDescription("谱面下载量 "+count+" 次");}}});}
    private static void loadDownloads(Activity host,SongCatalogue.Song song,AlertDialog dialog,Map<Integer,TextView> views){new Thread(()->{try{Engine engine=new Engine(host);String topic=CommunityData.topic(song);JSONObject cached=CommunityRepository.cachedSong(host,engine,topic);if(cached!=null)showDownloads(host,dialog,views,cached);showDownloads(host,dialog,views,CommunityRepository.song(host,engine,topic));}catch(Exception unavailable){host.runOnUiThread(()->{if(host.isDestroyed()||!dialog.isShowing())return;for(TextView value:views.values())if(value.getText().toString().equals("—"))value.setContentDescription("谱面下载量暂不可用");});}},"song-downloads").start();}
    @Override protected void onDetachedFromWindow(){handler.removeCallbacksAndMessages(null);super.onDetachedFromWindow();}
}
